//! Golden vectors: `test-vectors/verdict-v1.json`.
//!
//! The file is generated by [`document`] (`cargo run -p fermata-verdict -- vectors`) and asserted
//! byte for byte by this crate's tests and by the escrow contract's tests, which rebuild the same
//! message on-chain and settle a hold with the recorded signature. The verdict values are the ones
//! in Fermata's EIP-712 vector (`contracts/test/fixtures/verdict-vector.json`), except the service
//! id, which is derived from a fixed owner and label as on Stellar.

use ed25519_dalek::SigningKey;
use serde::{Deserialize, Serialize};

use crate::{
    hashes, keys,
    service::{self, Owner},
    to_hex,
    verdict::{self, Domain, Verdict, OUTCOME_DELIVERED, OUTCOME_FAILED},
    MAINNET_PASSPHRASE, TESTNET_PASSPHRASE,
};

/// The verifier's Ed25519 seed: 31 zero bytes and a 1 (the EIP-712 vector used private key 1).
pub const SIGNER_SEED: [u8; 32] = {
    let mut seed = [0u8; 32];
    seed[31] = 1;
    seed
};
/// The service owner: the account whose public key is 32 bytes of 0x22.
pub const OWNER_PUBLIC_KEY: [u8; 32] = [0x22; 32];
pub const LABEL: &str = "quote";
/// The escrow's contract id: 30 zero bytes then 0x0fe1 (the EIP-712 vector's escrow was 0x…0fe1).
pub const CONTRACT_ID: [u8; 32] = {
    let mut id = [0u8; 32];
    id[30] = 0x0f;
    id[31] = 0xe1;
    id
};
/// A second contract id, for the domain-separation vector.
pub const OTHER_CONTRACT_ID: [u8; 32] = {
    let mut id = CONTRACT_ID;
    id[31] = 0xe2;
    id
};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Document {
    pub description: String,
    pub verdict_tag: String,
    pub service_tag: String,
    pub signer: SignerVector,
    pub service: ServiceVector,
    pub verdicts: Vec<VerdictVector>,
    pub hashes: HashVectors,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SignerVector {
    pub seed: String,
    pub public_key: String,
    pub address: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ServiceVector {
    pub owner: String,
    pub owner_xdr: String,
    pub label: String,
    pub label_text: String,
    pub service_id: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct VerdictVector {
    pub name: String,
    pub network_passphrase: String,
    pub network_id: String,
    pub contract: String,
    pub contract_id: String,
    pub verdict: Verdict,
    pub canonical: String,
    pub message: String,
    pub signature: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct HashVectors {
    pub request_hash: RequestHashVector,
    pub origin_hash: OriginHashVector,
    pub notary_key_hash: NotaryKeyHashVector,
    pub predicate_hash: PredicateHashVector,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct RequestHashVector {
    pub service_id: String,
    pub method: String,
    pub target: String,
    pub body: String,
    pub value: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct OriginHashVector {
    pub origin: String,
    pub canonical: String,
    pub value: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct NotaryKeyHashVector {
    pub key: String,
    pub value: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct PredicateHashVector {
    pub file: String,
    pub value: String,
}

/// The vector service id: derived from [`OWNER_PUBLIC_KEY`] and [`LABEL`].
pub fn vector_service_id() -> [u8; 32] {
    service::service_id(
        &Owner::Account(OWNER_PUBLIC_KEY),
        &service::label(LABEL).expect("valid label"),
    )
}

/// Fermata's vector verdict (callId 0x11…, …, issuedAt 1.7e9) for the derived service id.
pub fn vector_verdict(outcome: u32) -> Verdict {
    Verdict {
        call_id: [0x11; 32],
        service_id: vector_service_id(),
        request_hash: [0x33; 32],
        predicate_hash: [0x44; 32],
        outcome,
        presentation_hash: [0x55; 32],
        response_hash: [0x66; 32],
        issued_at: 1_700_000_000,
    }
}

fn verdict_vector(
    name: &str,
    passphrase: &str,
    contract_id: [u8; 32],
    verdict: Verdict,
) -> VerdictVector {
    let key = SigningKey::from_bytes(&SIGNER_SEED);
    let domain = Domain::new(passphrase, contract_id);
    VerdictVector {
        name: name.into(),
        network_passphrase: passphrase.into(),
        network_id: to_hex(&domain.network_id),
        contract: keys::contract_address(&contract_id),
        contract_id: to_hex(&contract_id),
        canonical: to_hex(&verdict.canonical_bytes()),
        message: to_hex(&verdict::message(&domain, &verdict)),
        signature: to_hex(&verdict::sign(&key, &domain, &verdict)),
        verdict,
    }
}

/// The whole golden-vector document.
pub fn document() -> Document {
    let key = SigningKey::from_bytes(&SIGNER_SEED);
    let public_key = key.verifying_key().to_bytes();
    let owner = Owner::Account(OWNER_PUBLIC_KEY);
    let label = service::label(LABEL).expect("valid label");

    let mut request_service = [0u8; 32];
    request_service[31] = 1;
    let request_body = r#"{"symbol":"BTC-USD"}"#;
    let origin = hashes::Origin::parse("https://vendor.fermata.test:8443").expect("valid origin");
    let notary_key =
        hex::decode("02466d7fcae563e5cb09a0d1870bb580344804617879a14949cf22285f1bae3f27")
            .expect("valid hex");
    let predicate = include_bytes!("../../../predicates/quote-v1.json");

    Document {
        description: "Golden vectors for Fermata on Stellar. Generated by `cargo run -p fermata-verdict -- vectors`; asserted byte for byte by crates/fermata-verdict and contracts/escrow tests. All byte strings are lower-case hex.".into(),
        verdict_tag: String::from_utf8(verdict::VERDICT_TAG.to_vec()).expect("ASCII"),
        service_tag: String::from_utf8(service::SERVICE_TAG.to_vec()).expect("ASCII"),
        signer: SignerVector {
            seed: to_hex(&SIGNER_SEED),
            public_key: to_hex(&public_key),
            address: keys::account_address(&public_key),
        },
        service: ServiceVector {
            owner: owner.address(),
            owner_xdr: to_hex(&owner.sc_val_xdr()),
            label: to_hex(&label),
            label_text: LABEL.into(),
            service_id: to_hex(&vector_service_id()),
        },
        verdicts: vec![
            verdict_vector(
                "delivered on testnet",
                TESTNET_PASSPHRASE,
                CONTRACT_ID,
                vector_verdict(OUTCOME_DELIVERED),
            ),
            verdict_vector(
                "failed on testnet",
                TESTNET_PASSPHRASE,
                CONTRACT_ID,
                vector_verdict(OUTCOME_FAILED),
            ),
            verdict_vector(
                "delivered on mainnet (same verdict, another network)",
                MAINNET_PASSPHRASE,
                CONTRACT_ID,
                vector_verdict(OUTCOME_DELIVERED),
            ),
            verdict_vector(
                "delivered on testnet, another escrow",
                TESTNET_PASSPHRASE,
                OTHER_CONTRACT_ID,
                vector_verdict(OUTCOME_DELIVERED),
            ),
        ],
        hashes: HashVectors {
            request_hash: RequestHashVector {
                service_id: to_hex(&request_service),
                method: "POST".into(),
                target: "/v1/quote".into(),
                body: request_body.into(),
                value: to_hex(&hashes::request_hash(
                    &request_service,
                    "POST",
                    "/v1/quote",
                    request_body.as_bytes(),
                )),
            },
            origin_hash: OriginHashVector {
                origin: "https://vendor.fermata.test:8443".into(),
                canonical: origin.canonical(),
                value: to_hex(&origin.hash()),
            },
            notary_key_hash: NotaryKeyHashVector {
                key: to_hex(&notary_key),
                value: to_hex(&hashes::notary_key_hash(&notary_key)),
            },
            predicate_hash: PredicateHashVector {
                file: "predicates/quote-v1.json".into(),
                value: to_hex(&hashes::predicate_hash(predicate)),
            },
        },
    }
}

/// The document as committed: pretty JSON with a trailing newline.
pub fn document_json() -> String {
    let mut json = serde_json::to_string_pretty(&document()).expect("serializable");
    json.push('\n');
    json
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{parse_hex, verdict::MESSAGE_LEN};

    const COMMITTED: &str = include_str!("../../../test-vectors/verdict-v1.json");

    fn committed() -> Document {
        serde_json::from_str(COMMITTED).expect("test-vectors/verdict-v1.json parses")
    }

    /// The committed file is exactly what the generator prints; regenerate deliberately if the
    /// encoding ever changes (and bump the tag's version).
    #[test]
    fn committed_file_is_current() {
        assert_eq!(COMMITTED, document_json());
    }

    /// Recomputes every value from the raw inputs in the file, independently of `document()`.
    #[test]
    fn committed_values_recompute() {
        let doc = committed();
        let seed = parse_hex::<32>(&doc.signer.seed).unwrap();
        let key = SigningKey::from_bytes(&seed);
        let public_key = key.verifying_key().to_bytes();
        assert_eq!(doc.signer.public_key, to_hex(&public_key));
        assert_eq!(keys::public_key(&doc.signer.address), Ok(public_key));

        let owner = Owner::parse(&doc.service.owner).unwrap();
        let label = service::label(&format!("0x{}", doc.service.label)).unwrap();
        assert_eq!(service::label_text(&label).unwrap(), doc.service.label_text);
        assert_eq!(doc.service.owner_xdr, to_hex(&owner.sc_val_xdr()));
        assert_eq!(
            doc.service.service_id,
            to_hex(&service::service_id(&owner, &label))
        );

        assert_eq!(doc.verdicts.len(), 4);
        for v in &doc.verdicts {
            let contract_id = keys::contract_id(&v.contract).unwrap();
            assert_eq!(v.contract_id, to_hex(&contract_id));
            let domain = Domain::new(&v.network_passphrase, contract_id);
            assert_eq!(v.network_id, to_hex(&domain.network_id));
            assert_eq!(v.canonical, to_hex(&v.verdict.canonical_bytes()));
            let message = verdict::message(&domain, &v.verdict);
            assert_eq!(message.len(), MESSAGE_LEN);
            assert_eq!(v.message, to_hex(&message));
            assert_eq!(
                v.message,
                format!(
                    "{}{}{}{}",
                    to_hex(verdict::VERDICT_TAG),
                    v.network_id,
                    v.contract_id,
                    v.canonical
                )
            );
            let signature = parse_hex::<64>(&v.signature).unwrap();
            assert_eq!(signature, verdict::sign(&key, &domain, &v.verdict));
            assert_eq!(
                verdict::verify(&public_key, &domain, &v.verdict, &signature),
                Ok(())
            );
        }
        // Domain separation: one verdict, three domains, three different signatures.
        let sigs: Vec<&str> = [0, 2, 3]
            .iter()
            .map(|&i| doc.verdicts[i].signature.as_str())
            .collect();
        assert_eq!(doc.verdicts[0].verdict, doc.verdicts[2].verdict);
        assert_eq!(doc.verdicts[0].verdict, doc.verdicts[3].verdict);
        assert!(sigs[0] != sigs[1] && sigs[0] != sigs[2] && sigs[1] != sigs[2]);
    }

    #[test]
    fn committed_hashes_recompute() {
        let h = committed().hashes;
        let sid = parse_hex::<32>(&h.request_hash.service_id).unwrap();
        assert_eq!(
            h.request_hash.value,
            to_hex(&hashes::request_hash(
                &sid,
                &h.request_hash.method,
                &h.request_hash.target,
                h.request_hash.body.as_bytes()
            ))
        );
        // Fermata's shared values, unchanged by the port.
        assert_eq!(
            h.request_hash.value,
            "e8b23a0b9ea8101a4a0173a94062d4c5a197bc08b706e069c58eafccc47444b7"
        );
        assert_eq!(
            h.origin_hash.value,
            "99d1433da9b4903068a8548272ad3128e24be018828f8b1f14282b37b8261f29"
        );
        assert_eq!(
            h.notary_key_hash.value,
            "138b5a9c7e4489edde45496ce6770b6d91d5a0bcebb81ead85a3704242008aff"
        );
        assert_eq!(
            h.predicate_hash.value,
            "f9607cf217c0df0ef28de1cfbf3aa69c87f8a70d61a4557f5a7815958754c3e6"
        );
    }
}
